import type { ActorContext, CXCase, CXCaseStatus, DigitalEntitlement, EntitlementStatus, ExperienceOverview, FeedbackEntry, FulfilmentException, FulfilmentPlan, FulfilmentStatus, HealthCheck, Incident, IncidentStatus, PhysicalWorkOrder, PilotCohort, ProductQualitySignal, ReadinessCheck, ReconciliationFinding, ReconciliationRun, RefundRequest, ReturnAuthorization, Shipment, ShipmentStatus, ExchangeOrder, ExecutiveDecision, ExecutiveMetric } from '../types'

type Client=Awaited<ReturnType<typeof createServiceClient>>
const view=(client:Client,name:string)=>client.from(`fc_os_${name}`)
const arr=(value:unknown):string[]=>Array.isArray(value)?value.map(String):[]
const num=(value:unknown,fallback=0)=>{const n=Number(value);return Number.isFinite(n)?n:fallback}
const iso=(value:unknown)=>typeof value==='string'&&value?value:null
const obj=(value:unknown):Record<string,unknown>=>value&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,unknown>:{}
const code=(prefix:string)=>`${prefix}-${new Date().toISOString().replace(/\D/g,'').slice(0,14)}-${randomUUID().slice(0,5).toUpperCase()}`
async function safe<T>(operation:()=>Promise<T>,fallback:T):Promise<T>{try{return await operation()}catch{return fallback}}
async function audit(client:Client,actor:ActorContext,eventType:string,entityType:string,entityId:string,payload:Record<string,unknown>={}){await view(client,'audit_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,event_type:eventType,entity_type:entityType,entity_id:entityId,actor_id:actor.id,actor_name:actor.name,actor_role:actor.role,payload});await view(client,'outbox_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,event_type:eventType,aggregate_type:entityType,aggregate_id:entityId,payload:{...payload,actor},status:'pending'})}
export function actorFromUser(user:any):ActorContext{return{id:String(user?.id||user?.email||'unknown'),name:String(user?.full_name||user?.name||user?.email||'Utilisateur ANGELCARE'),role:String(user?.role||user?.role_key||'operator')}}

function mapPlan(row:any,items:any[]):FulfilmentPlan{return{id:String(row.id),code:String(row.code||''),universe:row.universe==='b2b'?'b2b':'b2c',customerId:String(row.customer_id||''),customerName:String(row.customer_name||''),orderId:String(row.order_id||''),orderNumber:String(row.order_number||''),deliveryNoteIds:arr(row.delivery_note_ids),mode:row.mode||'physical',status:row.status||'draft',priority:row.priority||'standard',siteId:iso(row.site_id),deliveryAddress:obj(row.delivery_address),promisedAt:iso(row.promised_at),owner:String(row.owner||''),items:items.filter(i=>String(i.fulfilment_plan_id)===String(row.id)).map(i=>({id:String(i.id),orderItemId:String(i.order_item_id||''),description:String(i.description||''),releaseIds:arr(i.release_ids),quantity:num(i.quantity),physicalQuantity:num(i.physical_quantity),digitalQuantity:num(i.digital_quantity),allocatedQuantity:num(i.allocated_quantity),pickedQuantity:num(i.picked_quantity),packedQuantity:num(i.packed_quantity),dispatchedQuantity:num(i.dispatched_quantity),deliveredQuantity:num(i.delivered_quantity),status:i.status||'pending',exceptionReason:iso(i.exception_reason)})),shipments:arr(row.shipment_ids),entitlementIds:arr(row.entitlement_ids),openExceptions:num(row.open_exceptions),createdAt:iso(row.created_at),updatedAt:iso(row.updated_at)}}
function mapShipment(row:any,events:any[]):Shipment{return{id:String(row.id),code:String(row.code||''),fulfilmentPlanId:String(row.fulfilment_plan_id||''),deliveryNoteId:iso(row.delivery_note_id),carrier:String(row.carrier||''),trackingNumber:iso(row.tracking_number),status:row.status||'draft',recipientName:String(row.recipient_name||''),recipientPhone:String(row.recipient_phone||''),address:obj(row.address),packageCount:num(row.package_count),weightKg:num(row.weight_kg),dispatchedAt:iso(row.dispatched_at),deliveredAt:iso(row.delivered_at),proofStorageObjectId:iso(row.proof_storage_object_id),exceptionReason:iso(row.exception_reason),events:events.filter(e=>String(e.shipment_id)===String(row.id)).map(e=>({id:String(e.id),status:e.status,detail:String(e.detail||''),occurredAt:String(e.occurred_at||'')}))}}
function mapEntitlement(row:any):DigitalEntitlement{return{id:String(row.id),code:String(row.code||''),fulfilmentPlanId:String(row.fulfilment_plan_id||''),customerId:String(row.customer_id||''),learnerId:iso(row.learner_id),releaseId:String(row.release_id||''),deliverableId:String(row.deliverable_id||''),status:row.status||'draft',accessTokenHint:String(row.access_token_hint||''),startsAt:iso(row.starts_at),expiresAt:iso(row.expires_at),downloadLimit:row.download_limit===null?null:num(row.download_limit),downloadCount:num(row.download_count),lastAccessAt:iso(row.last_access_at),replacedById:iso(row.replaced_by_id),createdAt:iso(row.created_at)}}
function mapCase(row:any,items:any[]):CXCase{return{id:String(row.id),code:String(row.code||''),universe:row.universe==='b2b'?'b2b':'b2c',customerId:String(row.customer_id||''),customerName:String(row.customer_name||''),caseType:row.case_type,status:row.status,severity:row.severity,subject:String(row.subject||''),description:String(row.description||''),orderId:iso(row.order_id),deliveryNoteId:iso(row.delivery_note_id),invoiceId:iso(row.invoice_id),fulfilmentPlanId:iso(row.fulfilment_plan_id),items:items.filter(i=>String(i.case_id)===String(row.id)).map(i=>({id:String(i.id),caseId:String(i.case_id),sourceType:i.source_type,sourceId:String(i.source_id||''),lineId:iso(i.line_id),description:String(i.description||''),quantity:num(i.quantity),eligibleQuantity:num(i.eligible_quantity),requestedResolution:String(i.requested_resolution||''),approvedResolution:iso(i.approved_resolution)})),evidenceCount:num(row.evidence_count),owner:iso(row.owner),slaDueAt:iso(row.sla_due_at),eligibilityDecision:iso(row.eligibility_decision),resolution:iso(row.resolution),customerConfirmedAt:iso(row.customer_confirmed_at),qualitySignalIds:arr(row.quality_signal_ids),createdAt:iso(row.created_at),updatedAt:iso(row.updated_at)}}
function mapSignal(row:any):ProductQualitySignal{return{id:String(row.id),code:String(row.code||''),collectionId:iso(row.collection_id),releaseId:iso(row.release_id),deliverableId:iso(row.deliverable_id),caseId:iso(row.case_id),signalType:String(row.signal_type||''),severity:row.severity||'medium',status:row.status||'new',title:String(row.title||''),detail:String(row.detail||''),occurrenceCount:num(row.occurrence_count,1),customerImpact:num(row.customer_impact),revenueImpactDh:num(row.revenue_impact_dh),recommendedAction:String(row.recommended_action||''),linkedOpportunityId:iso(row.linked_opportunity_id),linkedDesignId:iso(row.linked_design_id),linkedReviewId:iso(row.linked_review_id),createdAt:iso(row.created_at),updatedAt:iso(row.updated_at)}}

export async function loadExperienceOverview():Promise<ExperienceOverview>{return safe<ExperienceOverview>(async()=>{
  const client=await createServiceClient()
  const names=['fulfilment_plans','fulfilment_plan_items','physical_work_orders','shipment_records','shipment_events','digital_entitlements','fulfilment_exceptions','cx_cases','cx_case_items','return_authorizations','exchange_orders','refund_requests','feedback_entries','product_quality_signals','executive_metric_snapshots','executive_decisions','operational_health_checks','reconciliation_runs','reconciliation_findings','release_readiness_checks','pilot_cohorts','incident_records','incident_events']
  const results=await Promise.all(names.map(name=>view(client,name).select('*').eq('tenant_key',EXPERIENCE_TENANT_KEY)))
  const [plansR,planItemsR,workR,shipR,shipEventsR,entR,exceptionsR,casesR,caseItemsR,returnsR,exchangeR,refundR,feedbackR,signalsR,metricsR,decisionsR,healthR,reconR,reconFindR,readyR,pilotR,incidentR,incidentEventsR]=results
  const plans:FulfilmentPlan[]=(plansR.data||[]).map((row:any)=>mapPlan(row,planItemsR.data||[]))
  const shipments:Shipment[]=(shipR.data||[]).map((row:any)=>mapShipment(row,shipEventsR.data||[]))
  const entitlements:DigitalEntitlement[]=(entR.data||[]).map(mapEntitlement)
  const cases:CXCase[]=(casesR.data||[]).map((row:any)=>mapCase(row,caseItemsR.data||[]))
  const refunds:RefundRequest[]=(refundR.data||[]).map((row:any)=>({id:String(row.id),code:String(row.code||''),caseId:String(row.case_id||''),invoiceId:String(row.invoice_id||''),customerId:String(row.customer_id||''),customerName:String(row.customer_name||''),reason:String(row.reason||''),requestedAmountDh:num(row.requested_amount_dh),eligibleAmountDh:num(row.eligible_amount_dh),approvedAmountDh:num(row.approved_amount_dh),status:row.status,paymentMethod:String(row.payment_method||''),approvalNote:iso(row.approval_note),approvedBy:iso(row.approved_by),approvedAt:iso(row.approved_at),completedAt:iso(row.completed_at)}))
  const signals:ProductQualitySignal[]=(signalsR.data||[]).map(mapSignal)
  const healthChecks:HealthCheck[]=(healthR.data||[]).map((row:any)=>({id:String(row.id),key:String(row.check_key||''),label:String(row.label||''),domain:row.domain,status:row.status,latencyMs:row.latency_ms===null?null:num(row.latency_ms),detail:String(row.detail||''),checkedAt:iso(row.checked_at)}))
  const reconciliations:ReconciliationRun[]=(reconR.data||[]).map((row:any)=>({id:String(row.id),code:String(row.code||''),scope:arr(row.scope),status:row.status,startedAt:iso(row.started_at),completedAt:iso(row.completed_at),checkedRecords:num(row.checked_records),findingCount:num(row.finding_count),blockingCount:num(row.blocking_count),findings:(reconFindR.data||[]).filter((f:any)=>String(f.run_id)===String(row.id)).map((f:any)=>({id:String(f.id),runId:String(f.run_id),domain:f.domain,severity:f.severity,recordType:String(f.record_type||''),recordId:String(f.record_id||''),expected:String(f.expected_value||''),actual:String(f.actual_value||''),status:f.status,resolution:iso(f.resolution)}))}))
  const readiness:ReadinessCheck[]=(readyR.data||[]).map((row:any)=>({id:String(row.id),key:String(row.check_key||''),domain:row.domain,label:String(row.label||''),status:row.status,evidence:String(row.evidence||''),owner:String(row.owner||''),dueAt:iso(row.due_at),blocking:Boolean(row.blocking),updatedAt:iso(row.updated_at)}))
  const incidents:Incident[]=(incidentR.data||[]).map((row:any)=>({id:String(row.id),code:String(row.code||''),severity:row.severity,domain:String(row.domain||''),status:row.status,title:String(row.title||''),summary:String(row.summary||''),detectedAt:iso(row.detected_at),owner:iso(row.owner),customerImpact:String(row.customer_impact||''),financialImpactDh:num(row.financial_impact_dh),rootCause:iso(row.root_cause),resolution:iso(row.resolution),events:(incidentEventsR.data||[]).filter((e:any)=>String(e.incident_id)===String(row.id)).map((e:any)=>({id:String(e.id),status:e.status,detail:String(e.detail||''),occurredAt:String(e.occurred_at||'')}))}))
  const readinessPercent=readiness.length?Math.round(readiness.filter(x=>x.status==='passed'||x.status==='waived').length/readiness.length*100):0
  const healthStatus=healthChecks.some(x=>x.status==='critical')?'critical':healthChecks.some(x=>x.status==='degraded')?'degraded':healthChecks.length?'healthy':'unknown'
  const workOrders:PhysicalWorkOrder[]=(workR.data||[]).map((r:any)=>({id:String(r.id),code:String(r.code||''),fulfilmentPlanId:String(r.fulfilment_plan_id||''),status:r.status,zone:String(r.zone||''),assignedTo:iso(r.assigned_to),pickProgress:num(r.pick_progress),packProgress:num(r.pack_progress),qualityStatus:r.quality_status,dueAt:iso(r.due_at),createdAt:iso(r.created_at)}))
  const exceptions:FulfilmentException[]=(exceptionsR.data||[]).map((r:any)=>({id:String(r.id),fulfilmentPlanId:String(r.fulfilment_plan_id),type:r.exception_type,severity:r.severity,status:r.status,detail:String(r.detail||''),owner:iso(r.owner),dueAt:iso(r.due_at),resolution:iso(r.resolution),createdAt:iso(r.created_at)}))
  const returns:ReturnAuthorization[]=(returnsR.data||[]).map((r:any)=>({id:String(r.id),code:String(r.code||''),caseId:String(r.case_id||''),customerId:String(r.customer_id||''),status:r.status,pickupMethod:r.pickup_method,pickupAddress:obj(r.pickup_address),items:Array.isArray(r.items_snapshot)?r.items_snapshot:[],approvedBy:iso(r.approved_by),approvedAt:iso(r.approved_at),receivedAt:iso(r.received_at)}))
  const exchanges:ExchangeOrder[]=(exchangeR.data||[]).map((r:any)=>({id:String(r.id),code:String(r.code||''),caseId:String(r.case_id||''),status:r.status,replacementReleaseIds:arr(r.replacement_release_ids),replacementQuantities:(Array.isArray(r.replacement_quantities)?r.replacement_quantities:[]).map(Number),linkedFulfilmentPlanId:iso(r.linked_fulfilment_plan_id),approvedBy:iso(r.approved_by),createdAt:iso(r.created_at)}))
  const feedback:FeedbackEntry[]=(feedbackR.data||[]).map((r:any)=>({id:String(r.id),customerId:String(r.customer_id||''),caseId:iso(r.case_id),source:r.source,rating:r.rating===null?null:num(r.rating),csat:r.csat===null?null:num(r.csat),nps:r.nps===null?null:num(r.nps),comment:String(r.comment||''),consentToContact:Boolean(r.consent_to_contact),createdAt:iso(r.created_at)}))
  const executiveMetrics:ExecutiveMetric[]=(metricsR.data||[]).map((r:any)=>({key:String(r.metric_key||''),label:String(r.label||''),value:num(r.value),unit:r.unit,trend:num(r.trend),status:r.status,detail:String(r.detail||'')}))
  const decisions:ExecutiveDecision[]=(decisionsR.data||[]).map((r:any)=>({id:String(r.id),code:String(r.code||''),domain:r.domain,severity:r.severity,title:String(r.title||''),detail:String(r.detail||''),owner:String(r.owner||''),dueAt:iso(r.due_at),status:r.status,createdAt:iso(r.created_at)}))
  const pilots:PilotCohort[]=(pilotR.data||[]).map((r:any)=>({id:String(r.id),code:String(r.code||''),name:String(r.name||''),status:r.status,startsAt:iso(r.starts_at),endsAt:iso(r.ends_at),operatorIds:arr(r.operator_ids),customerIds:arr(r.customer_ids),scope:arr(r.scope),successCriteria:arr(r.success_criteria),openIssues:num(r.open_issues),createdAt:iso(r.created_at)}))
  return {sourceMode:'database',fulfilmentPlans:plans,workOrders,shipments,entitlements,exceptions,cases,returns,exchanges,refunds,feedback,qualitySignals:signals,executiveMetrics,decisions,healthChecks,reconciliations,readiness,pilots,incidents,metrics:{ordersReady:plans.filter((p:FulfilmentPlan)=>p.status==='ready').length,physicalInProgress:plans.filter((p:FulfilmentPlan)=>['picking','packing','dispatch_ready','dispatched'].includes(p.status)).length,digitalActive:entitlements.filter((e:DigitalEntitlement)=>e.status==='active').length,deliveryExceptions:exceptions.filter((e:FulfilmentException)=>e.status!=='resolved'&&e.status!=='waived').length,openCases:cases.filter((c:CXCase)=>!['closed','rejected'].includes(c.status)).length,refundExposureDh:refunds.filter((r:RefundRequest)=>!['rejected','cancelled','completed'].includes(r.status)).reduce((sum:number,r:RefundRequest)=>sum+r.requestedAmountDh,0),qualitySignalsOpen:signals.filter((s:ProductQualitySignal)=>!['resolved','dismissed'].includes(s.status)).length,healthStatus,readinessPercent}}
},controlledExperienceOverview)}

export async function createFulfilmentPlan(input:any,actor:ActorContext){const order=await getOrder(String(input.orderId));if(!order)throw new Error('Confirmed sales order not found.');if(!['confirmed','ready_for_fulfilment','partially_delivered','fully_delivered','partially_invoiced','fully_invoiced'].includes(order.status))throw new Error('Fulfilment requires a confirmed order.');const client=await createServiceClient();const id=randomUUID();const mode=input.mode==='digital'?'digital':input.mode==='hybrid'?'hybrid':'physical';const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('FUL'),universe:order.universe,customer_id:order.customerId,customer_name:order.customerName,order_id:order.id,order_number:order.number,delivery_note_ids:arr(input.deliveryNoteIds),mode,status:'ready',priority:input.priority||'standard',site_id:input.siteId||null,delivery_address:obj(input.deliveryAddress),promised_at:input.promisedAt||null,owner:actor.name,shipment_ids:[],entitlement_ids:[],open_exceptions:0};const {error}=await view(client,'fulfilment_plans').insert(row);if(error)throw error;const selected=Array.isArray(input.items)&&input.items.length?input.items:order.lines.map(line=>({orderItemId:line.id,quantity:Math.max(0,line.quantity-line.deliveredQuantity),physicalQuantity:line.deliveryRequired?Math.max(0,line.quantity-line.deliveredQuantity):0,digitalQuantity:line.digitalEntitlementRequired?Math.max(0,line.quantity-line.deliveredQuantity):0}));for(const item of selected){const line=order.lines.find(l=>l.id===String(item.orderItemId));if(!line)throw new Error('Order line not found.');const quantity=num(item.quantity);const remaining=Math.max(0,line.quantity-line.deliveredQuantity);if(quantity<=0||quantity>remaining)throw new Error(`Fulfilment quantity exceeds remaining quantity for ${line.description}.`);await view(client,'fulfilment_plan_items').insert({tenant_key:EXPERIENCE_TENANT_KEY,fulfilment_plan_id:id,order_item_id:line.id,description:line.description,release_ids:line.source.releaseIds,quantity,physical_quantity:num(item.physicalQuantity,line.deliveryRequired?quantity:0),digital_quantity:num(item.digitalQuantity,line.digitalEntitlementRequired?quantity:0),allocated_quantity:quantity,picked_quantity:0,packed_quantity:0,dispatched_quantity:0,delivered_quantity:0,status:'allocated'});}if(mode!=='digital')await view(client,'physical_work_orders').insert({tenant_key:EXPERIENCE_TENANT_KEY,code:code('PICK'),fulfilment_plan_id:id,status:'ready',zone:String(input.zone||'Main'),pick_progress:0,pack_progress:0,quality_status:'pending',due_at:input.promisedAt||null});await audit(client,actor,'fulfilment.plan.created','fulfilment_plan',id,{orderId:order.id,mode});revalidatePath('/flashcards-os/delivery/fulfilment');return{id,code:row.code}}

const allowedFulfilment:Record<FulfilmentStatus,FulfilmentStatus[]>={draft:['ready','cancelled'],ready:['picking','packing','dispatch_ready','cancelled','exception'],picking:['packing','exception','cancelled'],packing:['dispatch_ready','exception','cancelled'],dispatch_ready:['dispatched','exception','cancelled'],dispatched:['partially_delivered','delivered','exception'],partially_delivered:['delivered','exception'],delivered:['closed'],exception:['ready','picking','packing','dispatch_ready','dispatched','cancelled'],cancelled:[],closed:[]}
export async function transitionFulfilmentPlan(planId:string,status:FulfilmentStatus,note:string,actor:ActorContext){const overview=await loadExperienceOverview();const plan=overview.fulfilmentPlans.find(p=>p.id===planId);if(!plan)throw new Error('Fulfilment plan not found.');if(!allowedFulfilment[plan.status].includes(status))throw new Error(`Invalid fulfilment transition ${plan.status} → ${status}.`);const client=await createServiceClient();await view(client,'fulfilment_plans').update({status,updated_at:new Date().toISOString()}).eq('id',planId);await view(client,'fulfilment_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,fulfilment_plan_id:planId,event_type:'status_changed',from_status:plan.status,to_status:status,detail:note,actor_id:actor.id,actor_name:actor.name});await audit(client,actor,'fulfilment.status_changed','fulfilment_plan',planId,{from:plan.status,to:status,note});revalidatePath(`/flashcards-os/delivery/fulfilment/${planId}`);return{ok:true}}

export async function createShipment(input:any,actor:ActorContext){const overview=await loadExperienceOverview();const plan=overview.fulfilmentPlans.find(p=>p.id===String(input.fulfilmentPlanId));if(!plan)throw new Error('Fulfilment plan not found.');if(plan.mode==='digital')throw new Error('Digital-only fulfilment cannot create a physical shipment.');const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('SHP'),fulfilment_plan_id:plan.id,delivery_note_id:input.deliveryNoteId||null,carrier:String(input.carrier||'AngelCare Field'),tracking_number:input.trackingNumber||null,status:'booked',recipient_name:String(input.recipientName||plan.customerName),recipient_phone:String(input.recipientPhone||''),address:obj(input.address||plan.deliveryAddress),package_count:num(input.packageCount,1),weight_kg:num(input.weightKg),exception_reason:null};await view(client,'shipment_records').insert(row);await view(client,'shipment_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,shipment_id:id,status:'booked',detail:'Shipment created',occurred_at:new Date().toISOString(),actor_name:actor.name});await audit(client,actor,'shipment.created','shipment',id,{planId:plan.id,carrier:row.carrier});revalidatePath('/flashcards-os/delivery/shipments');return{id,code:row.code}}
const shipmentTransitions:Record<ShipmentStatus,ShipmentStatus[]>={draft:['booked'],booked:['labelled','handed_over','failed'],labelled:['handed_over','failed'],handed_over:['in_transit','failed'],in_transit:['out_for_delivery','delivered','failed','returned'],out_for_delivery:['delivered','failed','returned'],delivered:[],failed:['booked','returned'],returned:[]}
export async function addShipmentEvent(shipmentId:string,status:ShipmentStatus,detail:string,actor:ActorContext){const overview=await loadExperienceOverview();const shipment=overview.shipments.find(s=>s.id===shipmentId);if(!shipment)throw new Error('Shipment not found.');if(!shipmentTransitions[shipment.status].includes(status))throw new Error(`Invalid shipment transition ${shipment.status} → ${status}.`);const client=await createServiceClient();const update:any={status};if(status==='handed_over'||status==='in_transit')update.dispatched_at=new Date().toISOString();if(status==='delivered')update.delivered_at=new Date().toISOString();if(status==='failed'||status==='returned')update.exception_reason=detail;await view(client,'shipment_records').update(update).eq('id',shipmentId);await view(client,'shipment_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,shipment_id:shipmentId,status,detail,occurred_at:new Date().toISOString(),actor_name:actor.name});await audit(client,actor,'shipment.status_changed','shipment',shipmentId,{from:shipment.status,to:status});revalidatePath('/flashcards-os/delivery/shipments');return{ok:true}}

export async function issueDigitalEntitlement(input:any,actor:ActorContext){const overview=await loadExperienceOverview();const plan=overview.fulfilmentPlans.find(p=>p.id===String(input.fulfilmentPlanId));if(!plan)throw new Error('Fulfilment plan not found.');if(plan.mode==='physical')throw new Error('Physical-only fulfilment cannot issue a digital entitlement.');const production=await loadProductionOverview();const release=production.releases.find(r=>r.id===String(input.releaseId));if(!release||!['released','commercially_active'].includes(release.status))throw new Error('Digital entitlement requires an approved released product.');const deliverable=production.deliverables.find(d=>d.id===String(input.deliverableId));if(!deliverable||deliverable.reviewStatus!=='approved')throw new Error('Digital entitlement requires an approved deliverable.');const client=await createServiceClient();const id=randomUUID();const hint=randomUUID().replaceAll('-','').slice(0,8).toUpperCase();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('ENT'),fulfilment_plan_id:plan.id,customer_id:plan.customerId,learner_id:input.learnerId||null,release_id:release.id,deliverable_id:deliverable.id,status:'active',access_token_hint:hint,starts_at:input.startsAt||new Date().toISOString(),expires_at:input.expiresAt||null,download_limit:input.downloadLimit??null,download_count:0};await view(client,'digital_entitlements').insert(row);await view(client,'digital_entitlement_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,entitlement_id:id,event_type:'activated',detail:'Entitlement activated by authorised operator',actor_name:actor.name});await audit(client,actor,'digital_entitlement.activated','digital_entitlement',id,{planId:plan.id,releaseId:release.id});revalidatePath('/flashcards-os/delivery/digital-entitlements');return{id,code:row.code,accessTokenHint:hint}}
export async function changeEntitlementStatus(entitlementId:string,status:EntitlementStatus,detail:string,actor:ActorContext){const overview=await loadExperienceOverview();const entitlement=overview.entitlements.find(e=>e.id===entitlementId);if(!entitlement)throw new Error('Entitlement not found.');const client=await createServiceClient();await view(client,'digital_entitlements').update({status}).eq('id',entitlementId);await view(client,'digital_entitlement_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,entitlement_id:entitlementId,event_type:status,detail,actor_name:actor.name});await audit(client,actor,'digital_entitlement.status_changed','digital_entitlement',entitlementId,{from:entitlement.status,to:status});revalidatePath('/flashcards-os/delivery/digital-entitlements');return{ok:true}}

export async function openCXCase(input:any,actor:ActorContext){const severity=(['low','medium','high','critical'].includes(input.severity)?input.severity:'medium') as keyof typeof DEFAULT_CX_SLA_HOURS;const client=await createServiceClient();const id=randomUUID();const slaDueAt=new Date(Date.now()+DEFAULT_CX_SLA_HOURS[severity]*3600000).toISOString();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('CX'),universe:input.universe==='b2b'?'b2b':'b2c',customer_id:String(input.customerId),customer_name:String(input.customerName||''),case_type:String(input.caseType||'general_complaint'),severity,status:'opened',subject:String(input.subject||''),description:String(input.description||''),order_id:input.orderId||null,delivery_note_id:input.deliveryNoteId||null,invoice_id:input.invoiceId||null,fulfilment_plan_id:input.fulfilmentPlanId||null,evidence_count:0,owner:input.owner||actor.name,sla_due_at:slaDueAt,quality_signal_ids:[]};await view(client,'cx_cases').insert(row);for(const item of Array.isArray(input.items)?input.items:[])await view(client,'cx_case_items').insert({tenant_key:EXPERIENCE_TENANT_KEY,case_id:id,source_type:String(item.sourceType||'invoice'),source_id:String(item.sourceId||''),line_id:item.lineId||null,description:String(item.description||''),quantity:num(item.quantity),eligible_quantity:num(item.eligibleQuantity,item.quantity),requested_resolution:String(item.requestedResolution||'review')});await view(client,'cx_case_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,case_id:id,event_type:'opened',from_status:null,to_status:'opened',detail:'Case opened',actor_name:actor.name});await audit(client,actor,'cx.case.opened','cx_case',id,{caseType:row.case_type,severity});revalidatePath('/flashcards-os/delivery/customer-experience');return{id,code:row.code}}
const caseTransitions:Record<CXCaseStatus,CXCaseStatus[]>={opened:['eligibility_review','evidence_required','investigating','rejected'],eligibility_review:['evidence_required','investigating','resolution_proposed','rejected'],evidence_required:['investigating','rejected'],investigating:['resolution_proposed','evidence_required','rejected'],resolution_proposed:['approval_required','action_in_progress','rejected'],approval_required:['action_in_progress','rejected'],action_in_progress:['customer_confirmation','investigating'],customer_confirmation:['closed','investigating'],closed:[],rejected:[]}
export async function transitionCXCase(caseId:string,status:CXCaseStatus,detail:string,actor:ActorContext){const overview=await loadExperienceOverview();const item=overview.cases.find(c=>c.id===caseId);if(!item)throw new Error('CX case not found.');if(!caseTransitions[item.status].includes(status))throw new Error(`Invalid CX transition ${item.status} → ${status}.`);if(status==='closed'&&item.status!=='customer_confirmation')throw new Error('Customer confirmation is required before closure.');const client=await createServiceClient();const update:any={status,updated_at:new Date().toISOString()};if(status==='closed')update.customer_confirmed_at=new Date().toISOString();await view(client,'cx_cases').update(update).eq('id',caseId);await view(client,'cx_case_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,case_id:caseId,event_type:'status_changed',from_status:item.status,to_status:status,detail,actor_name:actor.name});await audit(client,actor,'cx.case.status_changed','cx_case',caseId,{from:item.status,to:status});revalidatePath(`/flashcards-os/delivery/customer-experience/${caseId}`);return{ok:true}}
export async function addCaseEvidence(caseId:string,input:any,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();await view(client,'cx_evidence').insert({id,tenant_key:EXPERIENCE_TENANT_KEY,case_id:caseId,evidence_type:String(input.type||'document'),label:String(input.label||''),reference:String(input.reference||''),storage_object_id:input.storageObjectId||null,recorded_by:actor.name});await view(client,'cx_cases').update({evidence_count:num(input.currentCount)+1,updated_at:new Date().toISOString()}).eq('id',caseId);await audit(client,actor,'cx.evidence.added','cx_case',caseId,{evidenceId:id});return{id}}

export async function createReturnAuthorization(input:any,actor:ActorContext){const overview=await loadExperienceOverview();const cx=overview.cases.find(c=>c.id===String(input.caseId));if(!cx)throw new Error('CX case not found.');if(!['return','partial_return','exchange','damaged_item','wrong_item','print_defect'].includes(cx.caseType))throw new Error('Case type is not return-eligible.');const client=await createServiceClient();const id=randomUUID();const items=(Array.isArray(input.items)?input.items:cx.items).map((item:any)=>({id:randomUUID(),caseItemId:String(item.caseItemId||item.id),description:String(item.description||''),quantity:num(item.quantity),receivedQuantity:0,condition:null,inspectionResult:null}));const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('RMA'),case_id:cx.id,customer_id:cx.customerId,status:'approved',pickup_method:input.pickupMethod||'agent_pickup',pickup_address:obj(input.pickupAddress),items_snapshot:items,approved_by:actor.name,approved_at:new Date().toISOString()};await view(client,'return_authorizations').insert(row);await audit(client,actor,'return.approved','return_authorization',id,{caseId:cx.id});revalidatePath('/flashcards-os/delivery/returns');return{id,code:row.code}}
export async function receiveReturn(returnId:string,input:any,actor:ActorContext){const overview=await loadExperienceOverview();const authorization=overview.returns.find(item=>item.id===returnId);if(!authorization)throw new Error('Return authorization not found.');const receivedItems=Array.isArray(input.items)?input.items:authorization.items;for(const received of receivedItems){const authorised=authorization.items.find(item=>item.id===String(received.id)||item.caseItemId===String(received.caseItemId));if(!authorised)throw new Error('Returned item is not authorised.');const receivedQuantity=num(received.receivedQuantity);if(receivedQuantity<0||receivedQuantity>authorised.quantity)throw new Error('Received return quantity exceeds authorised quantity.');}const client=await createServiceClient();await view(client,'return_authorizations').update({status:'received',items_snapshot:receivedItems,received_at:new Date().toISOString()}).eq('id',returnId);await view(client,'return_receipts').insert({tenant_key:EXPERIENCE_TENANT_KEY,return_authorization_id:returnId,received_by:actor.name,received_at:new Date().toISOString(),inspection_summary:String(input.inspectionSummary||''),storage_object_ids:arr(input.storageObjectIds)});await audit(client,actor,'return.received','return_authorization',returnId,{inspectionSummary:input.inspectionSummary||''});revalidatePath('/flashcards-os/delivery/returns');return{ok:true}}

export async function createExchangeOrder(input:any,actor:ActorContext){const overview=await loadExperienceOverview();const cx=overview.cases.find(c=>c.id===String(input.caseId));if(!cx)throw new Error('CX case not found.');const releases=arr(input.replacementReleaseIds);if(!releases.length)throw new Error('At least one replacement release is required.');const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('EXC'),case_id:cx.id,status:'approved',replacement_release_ids:releases,replacement_quantities:Array.isArray(input.replacementQuantities)?input.replacementQuantities.map(Number):releases.map(()=>1),linked_fulfilment_plan_id:null,approved_by:actor.name};await view(client,'exchange_orders').insert(row);await audit(client,actor,'exchange.approved','exchange_order',id,{caseId:cx.id});revalidatePath('/flashcards-os/delivery/returns');return{id,code:row.code}}

export async function createRefundRequest(input:any,actor:ActorContext){const invoice=await getInvoice(String(input.invoiceId));if(!invoice)throw new Error('Issued invoice not found.');const requested=Math.round(num(input.requestedAmountDh)*100)/100;const eligible=Math.max(0,Math.min(invoice.calculation.paidDh,invoice.calculation.totalDh-invoice.calculation.outstandingDh));if(requested<=0)throw new Error('Refund amount must be positive.');if(requested>eligible)throw new Error('Refund request exceeds paid or eligible value.');const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('REF'),case_id:String(input.caseId),invoice_id:invoice.id,customer_id:invoice.customerId,customer_name:invoice.customerName,reason:String(input.reason||''),requested_amount_dh:requested,eligible_amount_dh:eligible,approved_amount_dh:0,status:'approval_required',payment_method:String(input.paymentMethod||'original_method')};await view(client,'refund_requests').insert(row);await view(client,'refund_approvals').insert({tenant_key:EXPERIENCE_TENANT_KEY,refund_request_id:id,status:'pending',assigned_role:requested>MAX_REFUND_WITHOUT_EXECUTIVE_APPROVAL_DH?'executive_approver':'finance_controller',requested_by:actor.name,requested_at:new Date().toISOString()});await audit(client,actor,'refund.requested','refund_request',id,{invoiceId:invoice.id,requestedAmountDh:requested});revalidatePath('/flashcards-os/delivery/refunds');return{id,code:row.code}}
export async function decideRefund(refundId:string,decision:'approved'|'rejected',amountDh:number,note:string,actor:ActorContext){const overview=await loadExperienceOverview();const refund=overview.refunds.find(r=>r.id===refundId);if(!refund)throw new Error('Refund request not found.');const amount=Math.round(num(amountDh)*100)/100;if(decision==='approved'&&(amount<=0||amount>refund.eligibleAmountDh))throw new Error('Approved refund exceeds eligible value.');const client=await createServiceClient();await view(client,'refund_requests').update({status:decision,approved_amount_dh:decision==='approved'?amount:0,approval_note:note,approved_by:actor.name,approved_at:new Date().toISOString()}).eq('id',refundId);await view(client,'refund_approvals').update({status:decision,decided_by:actor.name,decided_at:new Date().toISOString(),decision_note:note}).eq('refund_request_id',refundId);await audit(client,actor,`refund.${decision}`,'refund_request',refundId,{amountDh:amount,note});revalidatePath('/flashcards-os/delivery/refunds');return{ok:true}}

export async function createQualitySignal(input:any,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('QS'),collection_id:input.collectionId||null,release_id:input.releaseId||null,deliverable_id:input.deliverableId||null,case_id:input.caseId||null,signal_type:String(input.signalType||'customer_feedback'),severity:input.severity||'medium',status:'new',title:String(input.title||''),detail:String(input.detail||''),occurrence_count:num(input.occurrenceCount,1),customer_impact:num(input.customerImpact,1),revenue_impact_dh:num(input.revenueImpactDh),recommended_action:String(input.recommendedAction||'Product review required.')};await view(client,'product_quality_signals').insert(row);if(input.caseId)await view(client,'cx_cases').update({quality_signal_ids:[id]}).eq('id',input.caseId);await audit(client,actor,'product_quality.signal_created','product_quality_signal',id,{releaseId:row.release_id,caseId:row.case_id});revalidatePath('/flashcards-os/delivery/quality-signals');return{id,code:row.code}}
export async function linkQualitySignal(signalId:string,input:any,actor:ActorContext){const client=await createServiceClient();const update={status:input.status||'linked_to_design',linked_opportunity_id:input.opportunityId||null,linked_design_id:input.designId||null,linked_review_id:input.reviewId||null,updated_at:new Date().toISOString()};await view(client,'product_quality_signals').update(update).eq('id',signalId);await view(client,'product_quality_signal_links').insert({tenant_key:EXPERIENCE_TENANT_KEY,signal_id:signalId,link_type:input.opportunityId?'product_opportunity':input.designId?'product_design':'quality_review',link_id:input.opportunityId||input.designId||input.reviewId,linked_by:actor.name});await audit(client,actor,'product_quality.signal_linked','product_quality_signal',signalId,update);return{ok:true}}

export async function runReconciliation(scopes:string[],actor:ActorContext){const selected=scopes.length?scopes:['orders','invoices','payments','balances','vault','entitlements','audit'];const client=await createServiceClient();const id=randomUUID();const started=new Date().toISOString();await view(client,'reconciliation_runs').insert({id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('REC'),scope:selected,status:'running',started_at:started,checked_records:0,finding_count:0,blocking_count:0});const findings:Omit<ReconciliationFinding,'id'|'runId'|'status'|'resolution'>[]=[];let checked=0
  if(selected.includes('orders')){for(const order of await listOrders()){checked++;for(const line of order.lines){const accounted=line.deliveredQuantity+Math.max(0,line.quantity-line.deliveredQuantity);if(Math.abs(accounted-line.quantity)>0.001)findings.push({domain:'orders',severity:'critical',recordType:'sales_order_item',recordId:line.id,expected:String(line.quantity),actual:String(accounted)})}}}
  if(selected.includes('invoices')){for(const invoice of await listInvoices()){checked++;if(Math.abs(invoice.calculation.totalDh-invoice.calculation.paidDh-invoice.calculation.outstandingDh)>0.02)findings.push({domain:'invoices',severity:'critical',recordType:'invoice',recordId:invoice.id,expected:String(invoice.calculation.totalDh),actual:String(invoice.calculation.paidDh+invoice.calculation.outstandingDh)})}}
  if(selected.includes('payments')){for(const payment of await listPayments()){checked++;const allocated=payment.allocations.reduce((s,a)=>s+a.amountDh,0);if(Math.abs(payment.amountDh-allocated-payment.unappliedAmountDh)>0.02)findings.push({domain:'payments',severity:'critical',recordType:'payment',recordId:payment.id,expected:String(payment.amountDh),actual:String(allocated+payment.unappliedAmountDh)})}}
  if(selected.includes('balances')){for(const balance of await listCustomerBalances()){checked++;const expected=balance.invoicedDh-balance.creditedDh-balance.paidDh;if(Math.abs(expected-balance.outstandingDh)>0.02)findings.push({domain:'balances',severity:'critical',recordType:'customer_balance',recordId:balance.customerId,expected:String(expected),actual:String(balance.outstandingDh)})}}
  if(selected.includes('vault')){const prod=await loadProductionOverview();for(const object of prod.storageObjects){checked++;if(!object.checksumSha256)findings.push({domain:'vault',severity:'high',recordType:'storage_object',recordId:object.id,expected:'SHA-256 checksum',actual:'missing'})}}
  if(selected.includes('entitlements')){const overview=await loadExperienceOverview();for(const entitlement of overview.entitlements){checked++;if(entitlement.status==='active'&&!entitlement.releaseId)findings.push({domain:'entitlements',severity:'critical',recordType:'digital_entitlement',recordId:entitlement.id,expected:'approved release',actual:'missing'})}}
  for(const finding of findings)await view(client,'reconciliation_findings').insert({tenant_key:EXPERIENCE_TENANT_KEY,run_id:id,domain:finding.domain,severity:finding.severity,record_type:finding.recordType,record_id:finding.recordId,expected_value:finding.expected,actual_value:finding.actual,status:'open'});const blocking=findings.filter(f=>f.severity==='critical').length;const status=blocking?'failed':findings.length?'warning':'passed';await view(client,'reconciliation_runs').update({status,completed_at:new Date().toISOString(),checked_records:checked,finding_count:findings.length,blocking_count:blocking}).eq('id',id);await audit(client,actor,'reconciliation.completed','reconciliation_run',id,{scope:selected,checked,findings:findings.length,blocking});revalidatePath('/flashcards-os/delivery/operations/reconciliation');return{id,status,checked,findings:findings.length,blocking}}

export async function executeHealthChecks(actor:ActorContext){const client=await createServiceClient();const checks:HealthCheck[]=[];const start=Date.now();try{await view(client,'operational_health_checks').select('id').limit(1);checks.push({id:randomUUID(),key:'database',label:'Flashcards OS database',domain:'database',status:'healthy',latencyMs:Date.now()-start,detail:'Database query succeeded.',checkedAt:new Date().toISOString()})}catch(error){checks.push({id:randomUUID(),key:'database',label:'Flashcards OS database',domain:'database',status:'critical',latencyMs:null,detail:error instanceof Error?error.message:'Database check failed.',checkedAt:new Date().toISOString()})}const prod=await loadProductionOverview();const node=prod.nodes[0];checks.push({id:randomUUID(),key:'windows_vault',label:'Windows Product Vault',domain:'storage',status:node?.status==='online'?'healthy':node?.status==='degraded'?'degraded':'critical',latencyMs:null,detail:node?`${node.label} · ${node.status}`:'No storage node registered.',checkedAt:new Date().toISOString()});checks.push({id:randomUUID(),key:'openrouter',label:'OpenRouter configuration',domain:'provider',status:process.env.OPENROUTER_API_KEY?'healthy':'degraded',latencyMs:null,detail:process.env.OPENROUTER_API_KEY?'Server credential configured.':'Credential missing; advisory intelligence disabled.',checkedAt:new Date().toISOString()});for(const item of checks)await view(client,'operational_health_checks').upsert({id:item.id,tenant_key:EXPERIENCE_TENANT_KEY,check_key:item.key,label:item.label,domain:item.domain,status:item.status,latency_ms:item.latencyMs,detail:item.detail,checked_at:item.checkedAt},{onConflict:'tenant_key,check_key'});await audit(client,actor,'health_checks.completed','operational_health',randomUUID(),{critical:checks.filter(c=>c.status==='critical').length});revalidatePath('/flashcards-os/delivery/operations/health');return checks}

