export async function createIncident(input:any,actor:ActorContext){const client=await createServiceClient();const id=randomUUID();const row={id,tenant_key:EXPERIENCE_TENANT_KEY,code:code('INC'),severity:input.severity||'medium',domain:String(input.domain||'operations'),status:'open',title:String(input.title||''),summary:String(input.summary||''),detected_at:new Date().toISOString(),owner:input.owner||actor.name,customer_impact:String(input.customerImpact||''),financial_impact_dh:num(input.financialImpactDh)};await view(client,'incident_records').insert(row);await view(client,'incident_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,incident_id:id,status:'open',detail:'Incident opened',occurred_at:new Date().toISOString(),actor_name:actor.name});await audit(client,actor,'incident.opened','incident',id,{severity:row.severity,domain:row.domain});revalidatePath('/flashcards-os/delivery/operations/incidents');return{id,code:row.code}}
const incidentTransitions:Record<IncidentStatus,IncidentStatus[]>={open:['investigating','mitigating'],investigating:['mitigating','monitoring','resolved'],mitigating:['monitoring','resolved'],monitoring:['resolved','investigating'],resolved:['closed','investigating'],closed:[]}
export async function transitionIncident(incidentId:string,status:IncidentStatus,detail:string,actor:ActorContext){const overview=await loadExperienceOverview();const incident=overview.incidents.find(i=>i.id===incidentId);if(!incident)throw new Error('Incident not found.');if(!incidentTransitions[incident.status].includes(status))throw new Error(`Invalid incident transition ${incident.status} → ${status}.`);const client=await createServiceClient();const update:any={status};if(status==='resolved')update.resolution=detail;await view(client,'incident_records').update(update).eq('id',incidentId);await view(client,'incident_events').insert({tenant_key:EXPERIENCE_TENANT_KEY,incident_id:incidentId,status,detail,occurred_at:new Date().toISOString(),actor_name:actor.name});await audit(client,actor,'incident.status_changed','incident',incidentId,{from:incident.status,to:status});return{ok:true}}

export async function captureExecutiveSnapshot(actor:ActorContext){const [experience,orders,invoices,payments,balances,production]=await Promise.all([loadExperienceOverview(),listOrders(),listInvoices(),listPayments(),listCustomerBalances(),loadProductionOverview()]);const now=new Date().toISOString();const values=[
  {key:'orders_ready',label:'Orders ready for fulfilment',value:experience.metrics.ordersReady,unit:'count',status:experience.metrics.ordersReady?'healthy':'unknown'},
  {key:'delivery_exceptions',label:'Open delivery exceptions',value:experience.metrics.deliveryExceptions,unit:'count',status:experience.metrics.deliveryExceptions?'degraded':'healthy'},
  {key:'open_cx_cases',label:'Open CX cases',value:experience.metrics.openCases,unit:'count',status:experience.metrics.openCases>5?'degraded':'healthy'},
  {key:'refund_exposure',label:'Refund exposure',value:experience.metrics.refundExposureDh,unit:'dh',status:experience.metrics.refundExposureDh>5000?'critical':experience.metrics.refundExposureDh?'degraded':'healthy'},
  {key:'outstanding_ar',label:'Outstanding receivables',value:balances.reduce((s,b)=>s+b.outstandingDh,0),unit:'dh',status:balances.some(b=>b.overdueDh>0)?'degraded':'healthy'},
  {key:'active_releases',label:'Commercial product releases',value:production.releases.filter(r=>r.status==='commercially_active').length,unit:'count',status:'healthy'},
  {key:'orders_total',label:'Orders governed',value:orders.length,unit:'count',status:'healthy'},
  {key:'invoices_total',label:'Invoices governed',value:invoices.length,unit:'count',status:'healthy'},
  {key:'payments_total',label:'Payments governed',value:payments.length,unit:'count',status:'healthy'},
] as const;const client=await createServiceClient();for(const item of values)await view(client,'executive_metric_snapshots').insert({tenant_key:EXPERIENCE_TENANT_KEY,snapshot_at:now,metric_key:item.key,label:item.label,value:item.value,unit:item.unit,trend:0,status:item.status,detail:'Deterministic operational snapshot.'});await audit(client,actor,'executive.snapshot_captured','executive_metric_snapshot',randomUUID(),{metrics:values.length});revalidatePath('/flashcards-os');return values}
export async function runExperienceIntelligence(task:any,context:unknown,actor:ActorContext){const result=await runExperienceAdvisory(task,context);const client=await createServiceClient();await view(client,'experience_intelligence_runs').insert({tenant_key:EXPERIENCE_TENANT_KEY,task,actor_id:actor.id,actor_name:actor.name,model_requested:result.modelRequested,model_used:result.modelUsed,prompt_tokens:result.promptTokens,completion_tokens:result.completionTokens,total_tokens:result.totalTokens,cost_usd:result.costUsd,latency_ms:result.latencyMs,input_hash:result.inputHash,result_payload:result});await audit(client,actor,'experience_intelligence.completed','experience_intelligence',randomUUID(),{task,modelUsed:result.modelUsed});return result}

export async function updatePhysicalWorkOrder(workOrderId:string,input:any,actor:ActorContext){
  const overview=await loadExperienceOverview();const workOrder=overview.workOrders.find(item=>item.id===workOrderId);if(!workOrder)throw new Error('Physical work order not found.');
  const pickProgress=Math.max(0,Math.min(100,num(input.pickProgress,workOrder.pickProgress)));const packProgress=Math.max(0,Math.min(100,num(input.packProgress,workOrder.packProgress)));
  const qualityStatus=['pending','passed','failed'].includes(input.qualityStatus)?input.qualityStatus:workOrder.qualityStatus;
  const allowedStatuses=['ready','picking','packing','qa_hold','dispatch_ready','completed','cancelled'];const status=allowedStatuses.includes(input.status)?input.status:workOrder.status;
  if(status==='dispatch_ready'&&(pickProgress<100||packProgress<100||qualityStatus!=='passed'))throw new Error('Dispatch readiness requires 100% picking, 100% packing and passed QA.');
  if(status==='completed'&&qualityStatus!=='passed')throw new Error('Completed work order requires passed QA.');
  const client=await createServiceClient();await view(client,'physical_work_orders').update({status,assigned_to:input.assignedTo??workOrder.assignedTo,pick_progress:pickProgress,pack_progress:packProgress,quality_status:qualityStatus,updated_at:new Date().toISOString()}).eq('id',workOrderId);
  await audit(client,actor,'physical_work_order.updated','physical_work_order',workOrderId,{status,pickProgress,packProgress,qualityStatus});revalidatePath('/flashcards-os/delivery/physical');return{ok:true}
}

